import re,os
d='/tmp/help'
f=open(os.path.join(d,'new.short.txt')).read().split('\n')
sec=None
for ln in f:
    if ln.endswith(':') and not ln.startswith(' '):
        sec=ln; print('SECTION',repr(ln)); continue
    if ln.startswith('  ') and ln.strip():
        m=re.match(r'^(\s+\S.*?)(  +)(\S.*)$', ln)
