//! Text reflowing used by the help renderer.
//!
//! Help strings are authored as paragraphs separated by blank lines. Single
//! newlines inside a paragraph are treated as spaces so that the paragraph is
//! reflowed to whatever width the terminal offers.

/// Reflow `text` into lines no longer than `width` columns.
///
/// Paragraphs (separated by one or more blank lines) are kept apart by an empty
/// line in the output.
pub fn reflow(text: &str, width: usize) -> Vec<String> {
    let width = width.max(1);
    let mut out = Vec::new();
    let mut first_para = true;
    for para in paragraphs(text) {
        if !first_para {
            out.push(String::new());
        }
        first_para = false;
        if para.is_empty() {
            continue;
        }
        greedy(&para, width, &mut out);
    }
    if out.is_empty() {
        out.push(String::new());
    }
    out
}

/// Split into paragraphs, collapsing intra-paragraph newlines into spaces.
fn paragraphs(text: &str) -> Vec<String> {
    let mut paras: Vec<String> = Vec::new();
    let mut current = String::new();
    for line in text.split('\n') {
        let trimmed = line.trim_end();
        if trimmed.trim().is_empty() {
            if !current.is_empty() {
                paras.push(std::mem::take(&mut current));
            } else if !paras.is_empty() || !current.is_empty() {
                // Consecutive blank lines collapse into a single break.
            }
        } else {
            if !current.is_empty() {
                current.push(' ');
            }
            current.push_str(trimmed.trim_start());
        }
    }
    if !current.is_empty() {
        paras.push(current);
    }
    paras
}

fn greedy(para: &str, width: usize, out: &mut Vec<String>) {
    let mut line = String::new();
    let mut line_len = 0usize;
    for word in para.split(' ').filter(|w| !w.is_empty()) {
        let wlen = display_width(word);
        if line_len == 0 {
            line.push_str(word);
            line_len = wlen;
        } else if line_len + 1 + wlen <= width {
            line.push(' ');
            line.push_str(word);
            line_len += 1 + wlen;
        } else {
            out.push(std::mem::take(&mut line));
            line.push_str(word);
            line_len = wlen;
        }
    }
    if !line.is_empty() || out.is_empty() {
        out.push(line);
    }
}

/// Character count, ignoring ANSI escape sequences.
pub fn display_width(s: &str) -> usize {
    let mut n = 0;
    let mut chars = s.chars();
    while let Some(c) = chars.next() {
        if c == '\u{1b}' {
            for c2 in chars.by_ref() {
                if c2.is_ascii_alphabetic() {
                    break;
                }
            }
        } else {
            n += 1;
        }
    }
    n
}

