//! A miniature command line parser and help renderer.
//!
//! Only the subset of behaviour that StGit's interface relies on is modelled:
//! flags, options with required or optional values, positional arguments,
//! argument groups used for `--help` headings, and nested subcommands.

use crate::wrap;

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ValueKind {
    /// No value; presence is all that matters.
    Flag,
    /// `--opt <value>` or `--opt=<value>`.
    Required,
    /// `--opt` or `--opt=<value>`; the separate-word form is not accepted.
    Optional,
}

#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum ArgKind {
    Opt,
    Positional,
}

#[derive(Clone)]
pub struct Arg {
    pub id: String,
    pub short: Option<char>,
    pub long: Option<String>,
    pub value: ValueKind,
    pub value_name: String,
    pub help: String,
    pub long_help: String,
    pub heading: String,
    pub multiple: bool,
    pub required: bool,
    pub hidden: bool,
    pub kind: ArgKind,
    pub allow_hyphen: bool,
    /// Ids this argument may not be combined with.
    pub conflicts: Vec<String>,
    /// Extra long form spellings accepted but not advertised.
    pub aliases: Vec<String>,
}

impl Arg {
    fn blank(id: &str) -> Arg {
        Arg {
            id: id.to_string(),
            short: None,
            long: None,
            value: ValueKind::Flag,
            value_name: String::new(),
            help: String::new(),
            long_help: String::new(),
            heading: String::new(),
            multiple: false,
            required: false,
            hidden: false,
            kind: ArgKind::Opt,
            allow_hyphen: false,
            conflicts: Vec::new(),
            aliases: Vec::new(),
        }
    }

    /// A boolean flag such as `-a, --all`.
    pub fn flag(id: &str) -> Arg {
        let mut a = Arg::blank(id);
        a.long = Some(id.to_string());
        a
    }

    /// An option taking a mandatory value.
    pub fn opt(id: &str, value_name: &str) -> Arg {
        let mut a = Arg::blank(id);
        a.long = Some(id.to_string());
        a.value = ValueKind::Required;
        a.value_name = value_name.to_string();
        a
    }

    /// An option whose value may be omitted (`--signoff[=<value>]`).
    pub fn optval(id: &str, value_name: &str) -> Arg {
        let mut a = Arg::opt(id, value_name);
        a.value = ValueKind::Optional;
        a
    }

    /// A positional argument.
    pub fn pos(id: &str) -> Arg {
        let mut a = Arg::blank(id);
        a.kind = ArgKind::Positional;
        a.value = ValueKind::Required;
        a.value_name = id.to_string();
        a
    }

    pub fn short(mut self, c: char) -> Arg {
        self.short = Some(c);
        self
    }

    /// Replace the advertised long spelling (the id stays the lookup key).
    pub fn long(mut self, l: &str) -> Arg {
        self.long = Some(l.to_string());
        self
    }

    pub fn no_long(mut self) -> Arg {
        self.long = None;
        self
    }

    pub fn alias(mut self, l: &str) -> Arg {
        self.aliases.push(l.to_string());
        self
    }

    pub fn value_name(mut self, n: &str) -> Arg {
        self.value_name = n.to_string();
        self
    }

    pub fn help(mut self, h: &str) -> Arg {
        self.help = h.to_string();
        self
    }

    pub fn long_help(mut self, h: &str) -> Arg {
        self.long_help = h.to_string();
        self
    }

    pub fn heading(mut self, h: &str) -> Arg {
        self.heading = h.to_string();
        self
    }

    pub fn multiple(mut self) -> Arg {
        self.multiple = true;
        self
    }

    pub fn required(mut self) -> Arg {
        self.required = true;
        self
    }

    pub fn hidden(mut self) -> Arg {
        self.hidden = true;
        self
    }

    pub fn allow_hyphen(mut self) -> Arg {
        self.allow_hyphen = true;
        self
    }

    pub fn conflicts(mut self, others: &[&str]) -> Arg {
        for o in others {
            self.conflicts.push(o.to_string());
        }
        self
    }

    /// How the argument is rendered in the two-column help listing.
    pub fn spec(&self) -> String {
        match self.kind {
            ArgKind::Positional => {
                let base = if self.required {
                    format!("<{}>", self.value_name)
                } else {
                    format!("[{}]", self.value_name)
                };
                if self.multiple {
                    format!("{base}...")
                } else {
                    base
                }
            }
            ArgKind::Opt => {
                let mut s = String::new();
                match (self.short, &self.long) {
                    (Some(c), Some(l)) => {
                        s.push_str(&format!("-{c}, --{l}"));
                    }
                    (Some(c), None) => s.push_str(&format!("-{c}")),
                    (None, Some(l)) => s.push_str(&format!("    --{l}")),
                    (None, None) => {}
                }
                match self.value {
                    ValueKind::Flag => {}
                    ValueKind::Required => {
                        if self.long.is_some() {
                            s.push_str(&format!(" <{}>", self.value_name));
                        } else {
                            s.push_str(&format!(" <{}>", self.value_name));
                        }
                    }
                    ValueKind::Optional => {
                        s.push_str(&format!("[=<{}>]", self.value_name));
                    }
                }
                s
            }
        }
    }
}

#[derive(Clone)]
pub struct Command {
    pub name: String,
    pub about: String,
    pub long_about: String,
    /// Usage lines minus the leading `Usage: ` / continuation padding.
    pub usage: Vec<String>,
    pub args: Vec<Arg>,
    pub subcommands: Vec<Command>,
    /// Heading used for the subcommand listing.
    pub sub_heading: String,
    /// Grouping label used by the top level help listing.
    pub group: String,
    pub aliases: Vec<String>,
    pub hidden: bool,
    /// Everything after the first positional is captured verbatim.
    pub trailing_var_arg: bool,
    pub requires_sub: bool,
}

impl Command {
    pub fn new(name: &str) -> Command {
        Command {
            name: name.to_string(),
            about: String::new(),
            long_about: String::new(),
            usage: Vec::new(),
            args: Vec::new(),
            subcommands: Vec::new(),
            sub_heading: "Commands".to_string(),
            group: String::new(),
            aliases: Vec::new(),
            hidden: false,
            trailing_var_arg: false,
            requires_sub: false,
        }
    }

    pub fn about(mut self, a: &str) -> Command {
        self.about = a.to_string();
        self
    }

    pub fn long_about(mut self, a: &str) -> Command {
        self.long_about = a.to_string();
        self
    }

    pub fn usage(mut self, lines: &[&str]) -> Command {
        self.usage = lines.iter().map(|s| s.to_string()).collect();
        self
    }

    pub fn arg(mut self, a: Arg) -> Command {
        self.args.push(a);
        self
    }

    pub fn args(mut self, list: Vec<Arg>) -> Command {
        self.args.extend(list);
        self
    }

    pub fn group(mut self, g: &str) -> Command {
        self.group = g.to_string();
        self
    }

    pub fn sub(mut self, c: Command) -> Command {
        self.subcommands.push(c);
        self
    }

    pub fn requires_sub(mut self) -> Command {
        self.requires_sub = true;
        self
    }

    pub fn trailing(mut self) -> Command {
        self.trailing_var_arg = true;
        self
    }

    fn find_long(&self, name: &str) -> Option<&Arg> {
        self.args.iter().find(|a| {
            a.kind == ArgKind::Opt
                && (a.long.as_deref() == Some(name) || a.aliases.iter().any(|x| x == name))
        })
    }

    fn find_short(&self, c: char) -> Option<&Arg> {
        self.args
            .iter()
            .find(|a| a.kind == ArgKind::Opt && a.short == Some(c))
    }

    fn positionals(&self) -> Vec<&Arg> {
        self.args
            .iter()
            .filter(|a| a.kind == ArgKind::Positional)
            .collect()
    }
}

/// Parsed command line for one command level.
#[derive(Default, Clone)]
pub struct Matches {
    /// Option occurrences keyed by argument id.
    pub values: Vec<(String, Option<String>)>,
    pub positional: Vec<(String, String)>,
    pub sub: Option<(String, Box<Matches>)>,
    /// Raw arguments following a literal `--`.
    pub after_dashdash: Vec<String>,
    pub saw_dashdash: bool,
}

impl Matches {
    pub fn is_present(&self, id: &str) -> bool {
        self.values.iter().any(|(k, _)| k == id)
    }

    pub fn count(&self, id: &str) -> usize {
        self.values.iter().filter(|(k, _)| k == id).count()
    }

    pub fn value(&self, id: &str) -> Option<&str> {
        self.values
            .iter()
            .rev()
            .find(|(k, _)| k == id)
            .and_then(|(_, v)| v.as_deref())
    }

    pub fn all_values(&self, id: &str) -> Vec<&str> {
        self.values
            .iter()
            .filter(|(k, _)| k == id)
            .filter_map(|(_, v)| v.as_deref())
            .collect()
    }

    /// Occurrences of an optional-value option, `None` for bare uses.
    pub fn occurrences(&self, id: &str) -> Vec<Option<&str>> {
        self.values
            .iter()
            .filter(|(k, _)| k == id)
            .map(|(_, v)| v.as_deref())
            .collect()
    }

    pub fn pos(&self, id: &str) -> Option<&str> {
        self.positional
            .iter()
            .find(|(k, _)| k == id)
            .map(|(_, v)| v.as_str())
    }

    pub fn pos_all(&self, id: &str) -> Vec<&str> {
        self.positional
            .iter()
            .filter(|(k, _)| k == id)
            .map(|(_, v)| v.as_str())
            .collect()
    }
}

/// Reason parsing stopped early.
pub enum ParseError {
    /// Help was requested; carries the rendered text.
    Help(String),
    /// `--version`.
    Version,
    /// A usage error; carries the message and the usage block to print.
    Usage(String, Vec<String>, Option<String>),
}

pub struct Parser<'a> {
    root: &'a Command,
}

/// Path of command names leading to the command being parsed.
fn usage_lines(path: &[&Command]) -> Vec<String> {
    let cmd = *path.last().unwrap();
    let prefix = path
        .iter()
        .map(|c| c.name.as_str())
        .collect::<Vec<_>>()
        .join(" ");
    if !cmd.usage.is_empty() {
        cmd.usage
            .iter()
            .map(|u| {
                if u.is_empty() {
                    prefix.clone()
                } else {
                    format!("{prefix} {u}")
                }
            })
            .collect()
    } else {
        vec![format!("{prefix} {}", auto_usage(cmd))]
    }
}

fn auto_usage(cmd: &Command) -> String {
    let mut parts: Vec<String> = Vec::new();
    let visible_opts = cmd
        .args
        .iter()
        .filter(|a| a.kind == ArgKind::Opt && !a.hidden)
        .count();
    if visible_opts > 0 {
        parts.push("[OPTIONS]".to_string());
    }
    for p in cmd.positionals() {
        if p.hidden {
            continue;
        }
        parts.push(p.spec());
    }
    if !cmd.subcommands.is_empty() {
        parts.push("<COMMAND>".to_string());
    }
    parts.join(" ")
}

impl<'a> Parser<'a> {
    pub fn new(root: &'a Command) -> Parser<'a> {
        Parser { root }
    }

    pub fn parse(&self, argv: &[String]) -> Result<Matches, ParseError> {
        let mut path = vec![self.root];
        self.parse_level(&mut path, argv, 0)
    }

    fn parse_level(
        &self,
        path: &mut Vec<&'a Command>,
        argv: &[String],
        start: usize,
    ) -> Result<Matches, ParseError> {
        let cmd: &'a Command = path.last().copied().unwrap();
        let mut m = Matches::default();
        let positionals = cmd.positionals();
        let mut pos_idx = 0usize;
        let mut i = start;
        let mut only_positional = false;
        let mut seen_positional = false;

        while i < argv.len() {
            let a = argv[i].clone();
            if only_positional {
                self.push_positional(cmd, &positionals, &mut pos_idx, &mut m, &a, path)?;
                i += 1;
                continue;
            }
            if a == "--" {
                m.saw_dashdash = true;
                only_positional = true;
                m.after_dashdash = argv[i + 1..].to_vec();
                i += 1;
                continue;
            }
            if a.starts_with("--") && a.len() > 2 {
                let body = &a[2..];
                let (name, inline) = match body.split_once('=') {
                    Some((n, v)) => (n, Some(v.to_string())),
                    None => (body, None),
                };
                let arg = match cmd.find_long(name) {
                    Some(x) => x,
                    None => {
                        if let Some(p) = positionals.get(pos_idx) {
                            if p.allow_hyphen {
                                self.push_positional(
                                    cmd,
                                    &positionals,
                                    &mut pos_idx,
                                    &mut m,
                                    &a,
                                    path,
                                )?;
                                i += 1;
                                continue;
                            }
                        }
                        return Err(self.unexpected(path, &a, !positionals.is_empty()));
                    }
                };
                if arg.id == "help" {
                    return Err(ParseError::Help(render_help(path, inline.is_none())));
                }
                if arg.id == "version" {
                    return Err(ParseError::Version);
                }
                match arg.value {
                    ValueKind::Flag => {
                        if inline.is_some() {
                            return Err(ParseError::Usage(
                                format!(
                                    "unexpected value '{}' for '--{}' found; no more were expected",
                                    inline.unwrap(),
                                    arg.long.clone().unwrap_or_default()
                                ),
                                usage_lines(path),
                                None,
                            ));
                        }
                        m.values.push((arg.id.clone(), None));
                    }
                    ValueKind::Optional => {
                        m.values.push((arg.id.clone(), inline));
                    }
                    ValueKind::Required => match inline {
                        Some(v) => m.values.push((arg.id.clone(), Some(v))),
                        None => {
                            if i + 1 < argv.len() {
                                m.values.push((arg.id.clone(), Some(argv[i + 1].clone())));
                                i += 1;
                            } else {
                                return Err(ParseError::Usage(
                                    format!(
                                        "a value is required for '{}' but none was supplied",
                                        arg.spec().trim_start()
                                    ),
                                    usage_lines(path),
                                    None,
                                ));
                            }
                        }
                    },
                }
                i += 1;
                continue;
            }
            if a.starts_with('-') && a.len() > 1 && a != "-" {
                // Cluster of short options.
                let chars: Vec<char> = a[1..].chars().collect();
                let mut ci = 0usize;
                let mut consumed_next = false;
                let mut unknown = false;
                while ci < chars.len() {
                    let c = chars[ci];
                    let arg = match cmd.find_short(c) {
                        Some(x) => x,
                        None => {
                            unknown = true;
                            break;
                        }
                    };
                    if arg.id == "help" {
                        return Err(ParseError::Help(render_help(path, false)));
                    }
                    match arg.value {
                        ValueKind::Flag => {
                            m.values.push((arg.id.clone(), None));
                            ci += 1;
                        }
                        ValueKind::Optional | ValueKind::Required => {
                            let rest: String = chars[ci + 1..].iter().collect();
                            let rest = rest.strip_prefix('=').map(|s| s.to_string()).unwrap_or(rest);
                            if !rest.is_empty() {
                                m.values.push((arg.id.clone(), Some(rest)));
                            } else if arg.value == ValueKind::Optional {
                                m.values.push((arg.id.clone(), None));
                            } else if i + 1 < argv.len() {
                                m.values.push((arg.id.clone(), Some(argv[i + 1].clone())));
                                consumed_next = true;
                            } else {
                                return Err(ParseError::Usage(
                                    format!(
                                        "a value is required for '{}' but none was supplied",
                                        arg.spec().trim_start()
                                    ),
                                    usage_lines(path),
                                    None,
                                ));
                            }
                            ci = chars.len();
                        }
                    }
                }
                if unknown {
                    if let Some(p) = positionals.get(pos_idx) {
                        if p.allow_hyphen {
                            self.push_positional(
                                cmd,
                                &positionals,
                                &mut pos_idx,
                                &mut m,
                                &a,
                                path,
                            )?;
                            i += 1;
                            continue;
                        }
                    }
                    return Err(self.unexpected(path, &a, !positionals.is_empty()));
                }
                i += 1;
                if consumed_next {
                    i += 1;
                }
                continue;
            }
            // Subcommand?
            if !cmd.subcommands.is_empty() && !seen_positional {
                if let Some(sc) = cmd
                    .subcommands
                    .iter()
                    .find(|s| s.name == a || s.aliases.iter().any(|x| *x == a))
                {
                    path.push(sc);
                    let sub = self.parse_level(path, argv, i + 1)?;
                    path.pop();
                    m.sub = Some((sc.name.clone(), Box::new(sub)));
                    return Ok(m);
                }
                if positionals.is_empty() {
                    return Err(self.unknown_sub(path, &a));
                }
            }
            seen_positional = true;
            self.push_positional(cmd, &positionals, &mut pos_idx, &mut m, &a, path)?;
            if cmd.trailing_var_arg {
                for extra in &argv[i + 1..] {
                    let p = positionals.last().unwrap();
                    m.positional.push((p.id.clone(), extra.clone()));
                }
                i = argv.len();
                continue;
            }
            i += 1;
        }

        if cmd.requires_sub && m.sub.is_none() {
            return Err(ParseError::Usage(
                "the following required arguments were not provided:\n  <COMMAND>".to_string(),
                usage_lines(path),
                None,
            ));
        }
        // Required arguments.
        let mut missing: Vec<String> = Vec::new();
        for p in &positionals {
            if p.required && m.pos(&p.id).is_none() {
                missing.push(p.spec());
            }
        }
        for o in cmd.args.iter().filter(|a| a.kind == ArgKind::Opt) {
            if o.required && !m.is_present(&o.id) {
                missing.push(o.spec().trim_start().to_string());
            }
        }
        if !missing.is_empty() {
            let mut msg =
                String::from("the following required arguments were not provided:");
            for x in &missing {
                msg.push_str(&format!("\n  {x}"));
            }
            return Err(ParseError::Usage(msg, usage_lines(path), None));
        }
        // Conflicts.
        for o in &cmd.args {
            if !m.is_present(&o.id) && m.pos(&o.id).is_none() {
                continue;
            }
            for c in &o.conflicts {
                let other = cmd.args.iter().find(|a| &a.id == c);
                let present = m.is_present(c) || m.pos(c).is_some();
                if present {
                    if let Some(other) = other {
                        return Err(ParseError::Usage(
                            format!(
                                "the argument '{}' cannot be used with '{}'",
                                o.spec().trim_start(),
                                other.spec().trim_start()
                            ),
                            usage_lines(path),
                            None,
                        ));
                    }
                }
            }
        }
        Ok(m)
    }

    fn push_positional(
        &self,
        _cmd: &Command,
        positionals: &[&Arg],
        pos_idx: &mut usize,
        m: &mut Matches,
        value: &str,
        path: &[&Command],
    ) -> Result<(), ParseError> {
        if *pos_idx >= positionals.len() {
            if let Some(last) = positionals.last() {
                if last.multiple {
                    m.positional.push((last.id.clone(), value.to_string()));
                    return Ok(());
                }
                return Err(ParseError::Usage(
                    format!(
                        "unexpected value '{}' for '{}' found; no more were expected",
                        value,
                        last.spec()
                    ),
                    usage_lines(path),
                    None,
                ));
            }
            return Err(self.unexpected(path, value, false));
        }
        let p = positionals[*pos_idx];
        m.positional.push((p.id.clone(), value.to_string()));
        if !p.multiple {
            *pos_idx += 1;
        }
        Ok(())
    }

    fn unexpected(&self, path: &[&Command], a: &str, has_pos: bool) -> ParseError {
        let tip = if has_pos && a.starts_with('-') {
            Some(format!("to pass '{a}' as a value, use '-- {a}'"))
        } else {
            None
        };
        ParseError::Usage(
            format!("unexpected argument '{a}' found"),
            usage_lines(path),
            tip,
        )
    }

    fn unknown_sub(&self, path: &[&Command], a: &str) -> ParseError {
        let cmd = *path.last().unwrap();
        let mut best: Option<(usize, &str)> = None;
        for s in cmd.subcommands.iter().filter(|s| !s.hidden) {
            let d = edit_distance(a, &s.name);
            if d * 3 <= s.name.len().max(a.len()) * 2 {
                if best.map(|(bd, _)| d < bd).unwrap_or(true) {
                    best = Some((d, &s.name));
                }
            }
        }
        let tip = best.map(|(_, n)| format!("a similar subcommand exists: '{n}'"));
        ParseError::Usage(
            format!("unrecognized subcommand '{a}'"),
            usage_lines(path),
            tip,
        )
    }
}

fn edit_distance(a: &str, b: &str) -> usize {
    let a: Vec<char> = a.chars().collect();
    let b: Vec<char> = b.chars().collect();
    let mut prev: Vec<usize> = (0..=b.len()).collect();
    let mut cur = vec![0usize; b.len() + 1];
    for i in 1..=a.len() {
        cur[0] = i;
        for j in 1..=b.len() {
            let cost = if a[i - 1] == b[j - 1] { 0 } else { 1 };
            cur[j] = (prev[j] + 1).min(cur[j - 1] + 1).min(prev[j - 1] + cost);
        }
        std::mem::swap(&mut prev, &mut cur);
    }
    prev[b.len()]
}

/// Terminal width used for help, capped the way StGit caps it.
pub fn term_width() -> usize {
    let raw = std::env::var("COLUMNS")
        .ok()
        .and_then(|s| s.trim().parse::<usize>().ok())
        .or_else(tty_width)
        .unwrap_or(100);
    raw.clamp(1, 88)
}

fn tty_width() -> Option<usize> {
    #[repr(C)]
    struct Winsize {
        ws_row: u16,
        ws_col: u16,
        ws_xpixel: u16,
        ws_ypixel: u16,
    }
    extern "C" {
        fn ioctl(fd: i32, request: u64, ...) -> i32;
    }
    let mut ws = Winsize {
        ws_row: 0,
        ws_col: 0,
        ws_xpixel: 0,
        ws_ypixel: 0,
    };
    // TIOCGWINSZ
    let rc = unsafe { ioctl(1, 0x5413, &mut ws as *mut Winsize) };
    if rc == 0 && ws.ws_col > 0 {
        Some(ws.ws_col as usize)
    } else {
        None
    }
}

/// Render the two-column entry listing for one heading.
fn render_section(out: &mut String, heading: &str, rows: &[(String, &Arg)], long: bool, width: usize) {
    out.push_str(&format!("\n{heading}:\n"));
    if long {
        let mut first = true;
        for (spec, arg) in rows {
            if !first {
                out.push('\n');
            }
            first = false;
            out.push_str(&format!("  {spec}\n"));
            let text = if arg.long_help.is_empty() {
                &arg.help
            } else {
                &arg.long_help
            };
            for line in wrap::reflow(text, width.saturating_sub(10).max(1)) {
                if line.is_empty() {
                    out.push_str("          \n");
                } else {
                    out.push_str(&format!("          {line}\n"));
                }
            }
        }
    } else {
        let col = rows
            .iter()
            .map(|(s, _)| wrap::display_width(s) + 2)
            .max()
            .unwrap_or(0)
            + 2;
        for (spec, arg) in rows {
            let start = 2 + wrap::display_width(spec);
            if arg.help.is_empty() {
                out.push_str(&format!("  {spec}\n"));
                continue;
            }
            let avail = width.saturating_sub(col).max(1);
            let lines = wrap::reflow(&arg.help, avail);
            if start + 2 > col {
                out.push_str(&format!("  {spec}\n"));
                for l in &lines {
                    out.push_str(&format!("{}{}\n", " ".repeat(col), l));
                }
            } else {
                out.push_str(&format!(
                    "  {spec}{}{}\n",
                    " ".repeat(col - start),
                    lines[0]
                ));
                for l in &lines[1..] {
                    out.push_str(&format!("{}{}\n", " ".repeat(col), l));
                }
            }
        }
    }
}

pub fn render_help(path: &[&Command], long: bool) -> String {
    let cmd = *path.last().unwrap();
    let width = term_width();
    let mut out = String::new();
    let about = if long && !cmd.long_about.is_empty() {
        &cmd.long_about
    } else {
        &cmd.about
    };
    if !about.is_empty() {
        for l in wrap::reflow(about, width) {
            out.push_str(&l);
            out.push('\n');
        }
    }
    out.push_str("\nUsage: ");
    let usage = usage_lines(path);
    for (i, u) in usage.iter().enumerate() {
        if i > 0 {
            out.push_str("       ");
        }
        out.push_str(u);
        out.push('\n');
    }
    if !cmd.subcommands.is_empty() {
        let subs: Vec<Command> = cmd.subcommands.iter().filter(|s| !s.hidden).cloned().collect();
        let mut groups: Vec<String> = Vec::new();
        for s in &subs {
            let g = if s.group.is_empty() {
                cmd.sub_heading.clone()
            } else {
                s.group.clone()
            };
            if !groups.contains(&g) {
                groups.push(g);
            }
        }
        for g in groups {
            let rows: Vec<(String, Arg)> = subs
                .iter()
                .filter(|s| {
                    let sg = if s.group.is_empty() {
                        cmd.sub_heading.clone()
                    } else {
                        s.group.clone()
                    };
                    sg == g
                })
                .map(|s| {
                    let mut a = Arg::blank(&s.name);
                    a.help = s.about.clone();
                    a.long_help = s.about.clone();
                    (s.name.clone(), a)
                })
                .collect();
            let refs: Vec<(String, &Arg)> =
                rows.iter().map(|(s, a)| (s.clone(), a)).collect();
            render_section(&mut out, &g, &refs, false, width);
        }
    }
    // Positional arguments.
    let pos: Vec<(String, &Arg)> = cmd
        .args
        .iter()
        .filter(|a| a.kind == ArgKind::Positional && !a.hidden)
        .map(|a| (a.spec(), a))
        .collect();
    if !pos.is_empty() {
        render_section(&mut out, "Arguments", &pos, long, width);
    }
    // Options, grouped by heading, "Options" first.
    let mut headings: Vec<String> = Vec::new();
    for a in cmd.args.iter().filter(|a| a.kind == ArgKind::Opt && !a.hidden) {
        let h = if a.heading.is_empty() {
            "Options".to_string()
        } else {
            a.heading.clone()
        };
        if !headings.contains(&h) {
            headings.push(h);
        }
    }
    for h in headings {
        let rows: Vec<(String, &Arg)> = cmd
            .args
            .iter()
            .filter(|a| a.kind == ArgKind::Opt && !a.hidden)
            .filter(|a| {
                let ah = if a.heading.is_empty() {
                    "Options".to_string()
                } else {
                    a.heading.clone()
                };
                ah == h
            })
            .map(|a| (a.spec(), a))
            .collect();
        render_section(&mut out, &h, &rows, long, width);
    }
    out
}

/// Standard `--color` option, present on nearly every command.
pub fn color_arg() -> Arg {
    Arg::opt("color", "when")
        .value_name("when")
        .help("When to colorize output: auto, always, ansi, never")
        .long_help(
            "Specify when to colorize the output.\n\n\
             `auto` (the default) enables colored output only when outputting to a \
             terminal or TTY. The `NO_COLOR` environment variable is respected.\n\n\
             `always` and `never` unconditionlly enable/disable colored output, \
             respectively.\n\n\
             `ansi` forces color to be output using ANSI escape sequences, even in a \
             Windows console.",
        )
}

pub fn help_arg() -> Arg {
    Arg::flag("help")
        .short('h')
        .help("Print help (see more with '--help')")
        .long_help("Print help (see a summary with '-h')")
}

