//! Thin wrappers around the `git` command line.

use std::collections::BTreeMap;
use std::ffi::OsStr;
use std::io::Write;
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};

use crate::error::{Error, Result};

/// Location and layout of the repository we are operating on.
pub struct Repo {
    pub git_dir: PathBuf,
    pub work_dir: Option<PathBuf>,
    /// Path from the top of the work tree to the current directory.
    pub prefix: String,
}

pub fn git() -> Command {
    let mut c = Command::new("git");
    c.env_remove("GIT_INDEX_FILE");
    c
}

/// Run git, returning trimmed stdout, or an error containing stderr.
pub fn run<I, S>(args: I) -> Result<String>
where
    I: IntoIterator<Item = S>,
    S: AsRef<OsStr>,
{
    let out = git().args(args).output().map_err(|e| Error::from(e))?;
    if out.status.success() {
        Ok(String::from_utf8_lossy(&out.stdout).trim_end_matches('\n').to_string())
    } else {
        Err(Error::Msg(
            String::from_utf8_lossy(&out.stderr).trim_end().to_string(),
        ))
    }
}

/// Run git, returning raw stdout bytes.
pub fn run_bytes<I, S>(args: I) -> Result<Vec<u8>>
where
    I: IntoIterator<Item = S>,
    S: AsRef<OsStr>,
{
    let out = git().args(args).output()?;
    if out.status.success() {
        Ok(out.stdout)
    } else {
        Err(Error::Msg(
            String::from_utf8_lossy(&out.stderr).trim_end().to_string(),
        ))
    }
}

/// Run git connected to the terminal; returns the exit status code.
pub fn run_status<I, S>(args: I) -> Result<i32>
where
    I: IntoIterator<Item = S>,
    S: AsRef<OsStr>,
{
    let st = git().args(args).status()?;
    Ok(st.code().unwrap_or(1))
}

/// Run git with stdin supplied from memory.
pub fn run_with_input<I, S>(args: I, input: &[u8]) -> Result<String>
where
    I: IntoIterator<Item = S>,
    S: AsRef<OsStr>,
{
    let mut child = git()
        .args(args)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::piped())
        .spawn()?;
    child.stdin.as_mut().unwrap().write_all(input)?;
    let out = child.wait_with_output()?;
    if out.status.success() {
        Ok(String::from_utf8_lossy(&out.stdout).trim_end_matches('\n').to_string())
    } else {
        Err(Error::Msg(
            String::from_utf8_lossy(&out.stderr).trim_end().to_string(),
        ))
    }
}

impl Repo {
    pub fn open() -> Result<Repo> {
        let out = git()
            .args(["rev-parse", "--git-dir", "--show-toplevel", "--show-prefix"])
            .output()?;
        if !out.status.success() {
            let cwd = std::env::current_dir()
                .ok()
                .map(|p| p.display().to_string())
                .unwrap_or_else(|| ".".to_string());
            let _ = cwd;
            return Err(Error::Msg(
                "Could not find a git repository in '.' or in any of its parents".to_string(),
            ));
        }
        let text = String::from_utf8_lossy(&out.stdout);
        let mut lines = text.lines();
        let git_dir = lines.next().unwrap_or(".git").to_string();
        let top = lines.next().map(|s| s.to_string());
        let prefix = lines.next().unwrap_or("").to_string();
        let git_dir = std::fs::canonicalize(&git_dir).unwrap_or_else(|_| PathBuf::from(&git_dir));
        Ok(Repo {
            git_dir,
            work_dir: top.map(PathBuf::from),
            prefix,
        })
    }

    pub fn stgit_dir(&self) -> PathBuf {
        self.git_dir.join("stgit")
    }

    pub fn current_branch(&self) -> Result<String> {
        let name = run(["symbolic-ref", "--short", "HEAD"])
            .map_err(|_| Error::Msg("not on branch, HEAD is detached".to_string()))?;
        Ok(name)
    }

    pub fn head_oid(&self) -> Result<String> {
        run(["rev-parse", "HEAD"])
    }
}

pub fn rev_parse(spec: &str) -> Result<String> {
    let out = git()
        .args(["rev-parse", "--verify", "--quiet", spec])
        .output()?;
    if out.status.success() {
        let s = String::from_utf8_lossy(&out.stdout).trim().to_string();
        if s.is_empty() {
            Err(Error::Msg(format!("invalid revision `{spec}`")))
        } else {
            Ok(s)
        }
    } else {
        Err(Error::Msg(format!("invalid revision `{spec}`")))
    }
}

pub fn ref_exists(name: &str) -> bool {
    git()
        .args(["show-ref", "--verify", "--quiet", name])
        .status()
        .map(|s| s.success())
        .unwrap_or(false)
}

pub fn cat_file(oid: &str) -> Result<Vec<u8>> {
    run_bytes(["cat-file", "-p", oid])
}

pub fn hash_object(data: &[u8]) -> Result<String> {
    run_with_input(["hash-object", "-w", "-t", "blob", "--stdin"], data)
}

pub fn commit_tree(tree: &str, parents: &[String], message: &str) -> Result<String> {
    let mut args: Vec<String> = vec!["commit-tree".into(), tree.into()];
