//! Stack metadata: reading and writing `refs/stacks/<branch>`.

use std::collections::BTreeMap;

use crate::error::{err, Error, Result};
use crate::git::{self, Repo};
use crate::json;

pub const STATE_VERSION: u32 = 5;

pub struct Stack {
    pub branch: String,
    pub state_commit: Option<String>,
    pub prev: Option<String>,
    pub head: String,
    pub applied: Vec<String>,
    pub unapplied: Vec<String>,
    pub hidden: Vec<String>,
    pub patches: BTreeMap<String, String>,
}

pub fn state_ref(branch: &str) -> String {
    format!("refs/stacks/{branch}")
}

pub fn patch_ref(branch: &str, patch: &str) -> String {
    format!("refs/patches/{branch}/{patch}")
}

pub fn is_initialized(branch: &str) -> bool {
    git::ref_exists(&state_ref(branch))
}

impl Stack {
    /// Load the stack for `branch`, failing if it has not been initialized.
    pub fn load(_repo: &Repo, branch: &str) -> Result<Stack> {
        let sref = state_ref(branch);
        if !git::ref_exists(&sref) {
            return err(format!(
                "StGit stack not initialized for branch `{branch}`"
            ));
        }
        let commit = git::rev_parse(&sref)?;
        let mut st = Stack::from_state_commit(branch, &commit)?;
        st.state_commit = Some(commit);
        Ok(st)
    }

    pub fn from_state_commit(branch: &str, commit: &str) -> Result<Stack> {
        let blob = git::cat_file(&format!("{commit}:stack.json"))?;
        let text = String::from_utf8_lossy(&blob).to_string();
