                .and_then(|x| x.as_array())
                .map(|a| a.iter().filter_map(|e| e.as_str().map(|s| s.to_string())).collect())
                .unwrap_or_default()
        };
        let mut patches = BTreeMap::new();
        if let Some(obj) = v.get("patches").and_then(|x| x.as_object()) {
            for (k, pv) in obj {
                if let Some(oid) = pv.get("oid").and_then(|x| x.as_str()) {
                    patches.insert(k.clone(), oid.to_string());
                }
            }
        }
        Ok(Stack {
            branch: branch.to_string(),
            state_commit: Some(commit.to_string()),
            prev: v.get("prev").and_then(|x| x.as_str()).map(|s| s.to_string()),
            head: v
                .get("head")
                .and_then(|x| x.as_str())
                .unwrap_or_default()
                .to_string(),
            applied: get_list("applied"),
            unapplied: get_list("unapplied"),
            hidden: get_list("hidden"),
            patches,
        })
    }

    pub fn top(&self) -> Option<&String> {
        self.applied.last()
    }

    /// Commit the top applied patch points at, or the branch base.
    pub fn top_oid(&self) -> String {
        match self.applied.last() {
            Some(p) => self.patches[p].clone(),
            None => self.head.clone(),
        }
    }

    /// Commit the stack is built on top of.
    pub fn base(&self) -> Result<String> {
        match self.applied.first() {
            Some(p) => {
                let c = git::read_commit(&self.patches[p])?;
                Ok(c.parents.first().cloned().unwrap_or_default())
            }
            None => Ok(self.head.clone()),
        }
    }

    pub fn all_patches(&self) -> Vec<String> {
        let mut v = self.applied.clone();
        v.extend(self.unapplied.clone());
        v.extend(self.hidden.clone());
        v
    }

    pub fn has_patch(&self, name: &str) -> bool {
        self.patches.contains_key(name)
    }

    pub fn oid_of(&self, name: &str) -> Result<String> {
        self.patches
            .get(name)
            .cloned()
            .ok_or_else(|| Error::Msg(format!("patch `{name}` does not exist")))
    }

    pub fn is_applied(&self, name: &str) -> bool {
        self.applied.iter().any(|p| p == name)
    }

    pub fn is_unapplied(&self, name: &str) -> bool {
        self.unapplied.iter().any(|p| p == name)
    }

    pub fn is_hidden(&self, name: &str) -> bool {
        self.hidden.iter().any(|p| p == name)
    }

    fn to_json(&self) -> String {
        let mut s = String::from("{\n");
        s.push_str(&format!("  \"version\": {},\n", STATE_VERSION));
        match &self.prev {
            Some(p) => s.push_str(&format!("  \"prev\": \"{p}\",\n")),
            None => s.push_str("  \"prev\": null,\n"),
        }
        s.push_str(&format!("  \"head\": \"{}\",\n", self.head));
        for (name, list) in [
            ("applied", &self.applied),
            ("unapplied", &self.unapplied),
            ("hidden", &self.hidden),
        ] {
            if list.is_empty() {
                s.push_str(&format!("  \"{name}\": [],\n"));
            } else {
                s.push_str(&format!("  \"{name}\": [\n"));
                for (i, p) in list.iter().enumerate() {
                    s.push_str(&format!("    \"{}\"", json::escape(p)));
                    if i + 1 < list.len() {
                        s.push(',');
                    }
                    s.push('\n');
                }
                s.push_str("  ],\n");
            }
        }
        if self.patches.is_empty() {
            s.push_str("  \"patches\": {}\n");
        } else {
            s.push_str("  \"patches\": {\n");
            let n = self.patches.len();
            for (i, (name, oid)) in self.patches.iter().enumerate() {
                s.push_str(&format!("    \"{}\": {{\n", json::escape(name)));
                s.push_str(&format!("      \"oid\": \"{oid}\"\n"));
                s.push_str("    }");
                if i + 1 < n {
                    s.push(',');
                }
                s.push('\n');
            }
            s.push_str("  }\n");
        }
        s.push('}');
        s
    }

    /// Human readable per-patch metadata stored alongside `stack.json`.
    fn patch_meta(&self, name: &str) -> Result<String> {
        let oid = self.oid_of(name)?;
        let c = git::read_commit(&oid)?;
        let top_tree = c.tree.clone();
        let bottom_tree = match c.parents.first() {
            Some(p) => git::read_commit(p)?.tree,
            None => top_tree.clone(),
        };
        let mut s = String::new();
        s.push_str(&format!("Bottom: {bottom_tree}\n"));
        s.push_str(&format!("Top:    {top_tree}\n"));
        s.push_str(&format!("Author: {}\n", c.author.name_email()));
        s.push_str(&format!(
            "Date:   {}\n",
            crate::date::format_meta(c.author.time, &c.author.offset)
        ));
        s.push('\n');
        let msg = c.message.trim_end_matches('\n');
        s.push_str(msg);
        s.push('\n');
        Ok(s)
    }

    /// Write a new stack state commit and move `refs/stacks/<branch>`.
    pub fn commit_state(&mut self, message: &str) -> Result<()> {
        let mut entries: BTreeMap<String, (String, String)> = BTreeMap::new();
        let json_oid = git::hash_object(self.to_json().as_bytes())?;
        entries.insert("stack.json".to_string(), ("100644".to_string(), json_oid));
        for name in self.patches.keys() {
            let meta = self.patch_meta(name)?;
            let oid = git::hash_object(meta.as_bytes())?;
            entries.insert(format!("patches/{name}"), ("100644".to_string(), oid));
        }
        let tree = git::make_tree(&entries)?;

        let prev_state = self.state_commit.clone();
        // The first parent forms a linear chain used by `stg log`.
        let simplified_parents: Vec<String> = match &prev_state {
            Some(p) => vec![git::read_commit(p)?.parents[0].clone()],
            None => vec![],
        };
        let log_commit = git::commit_tree(&tree, &simplified_parents, message)?;

        let mut parents = vec![log_commit];
        // Keep every referenced commit reachable from the state ref.
        let mut extra: Vec<String> = Vec::new();
        if !self.head.is_empty() {
            extra.push(self.head.clone());
        }
        for oid in self.patches.values() {
            if !extra.contains(oid) {
                extra.push(oid.clone());
            }
        }
        parents.extend(extra);
        if let Some(p) = &prev_state {
            parents.push(p.clone());
        }
        let state = git::commit_tree(&tree, &parents, message)?;
        git::update_ref(&state_ref(&self.branch), &state, message)?;
        self.prev = prev_state;
        self.state_commit = Some(state);
        self.sync_patch_refs()?;
        Ok(())
    }

    /// Keep `refs/patches/<branch>/<patch>` in step with the metadata.
    fn sync_patch_refs(&self) -> Result<()> {
        let prefix = format!("refs/patches/{}/", self.branch);
        let existing = git::run(["for-each-ref", "--format=%(refname) %(objectname)", &prefix])
            .unwrap_or_default();
        let mut have: BTreeMap<String, String> = BTreeMap::new();
        for line in existing.lines() {
            if let Some((r, o)) = line.split_once(' ') {
                if let Some(name) = r.strip_prefix(&prefix) {
                    have.insert(name.to_string(), o.to_string());
                }
            }
        }
        let mut input = String::new();
        for (name, oid) in &self.patches {
            if have.get(name).map(|o| o != oid).unwrap_or(true) {
                input.push_str(&format!("update {prefix}{name} {oid}\n"));
            }
        }
        for name in have.keys() {
            if !self.patches.contains_key(name) {
                input.push_str(&format!("delete {prefix}{name}\n"));
            }
        }
        if !input.is_empty() {
            git::run_with_input(["update-ref", "--stdin"], input.as_bytes())?;
        }
        Ok(())
    }

    /// Point the branch at the top of the stack.
    pub fn update_head_ref(&self, reason: &str) -> Result<()> {
        let oid = self.top_oid();
        git::update_ref(&format!("refs/heads/{}", self.branch), &oid, reason)
    }
}

/// Create the initial state for a branch.
pub fn initialize(repo: &Repo, branch: &str) -> Result<Stack> {
    if is_initialized(branch) {
        return err(format!(
            "StGit stack already initialized for branch `{branch}`"
        ));
    }
    let head = git::rev_parse(&format!("refs/heads/{branch}"))
        .map_err(|_| Error::Msg(format!("branch `{branch}` not found")))?;
    let _ = repo;
    let mut st = Stack {
        branch: branch.to_string(),
        state_commit: None,
        prev: None,
        head,
        applied: Vec::new(),
        unapplied: Vec::new(),
        hidden: Vec::new(),
        patches: BTreeMap::new(),
    };
    st.commit_state("initialize")?;
    Ok(st)
}

/// Load the stack, initializing it first if necessary.
pub fn load_or_init(repo: &Repo, branch: &str) -> Result<Stack> {
    if is_initialized(branch) {
        Stack::load(repo, branch)
    } else {
        initialize(repo, branch)
    }
}

