        '{' => {
            *i += 1;
            let mut m = BTreeMap::new();
            loop {
                skip_ws(b, i);
                if *i < b.len() && b[*i] == '}' {
                    *i += 1;
                    break;
                }
                let key = match parse_value(b, i)? {
                    Value::Str(s) => s,
                    _ => return None,
                };
