                if *i >= b.len() || b[*i] != ':' {
                    return None;
                }
                *i += 1;
                let val = parse_value(b, i)?;
                m.insert(key, val);
                skip_ws(b, i);
                if *i < b.len() && b[*i] == ',' {
                    *i += 1;
                }
            }
            Some(Value::Obj(m))
        }
        '[' => {
            *i += 1;
            let mut a = Vec::new();
            loop {
                skip_ws(b, i);
                if *i < b.len() && b[*i] == ']' {
                    *i += 1;
                    break;
                }
                a.push(parse_value(b, i)?);
                skip_ws(b, i);
                if *i < b.len() && b[*i] == ',' {
                    *i += 1;
                }
            }
            Some(Value::Arr(a))
        }
        '"' => {
            *i += 1;
            let mut s = String::new();
