//! Date formatting and parsing without external crates.

const MONTHS: [&str; 12] = [
    "Jan", "Feb", "Mar", "Apr", "May", "Jun", "Jul", "Aug", "Sep", "Oct", "Nov", "Dec",
];
const DAYS: [&str; 7] = ["Thu", "Fri", "Sat", "Sun", "Mon", "Tue", "Wed"];

pub struct Civil {
    pub year: i64,
    pub month: u32,
    pub day: u32,
    pub hour: u32,
    pub min: u32,
    pub sec: u32,
    /// Day of week index where 0 == Thursday (epoch day 0).
    pub wday: usize,
}

fn offset_seconds(offset: &str) -> i64 {
    let bytes = offset.as_bytes();
    if bytes.len() < 5 {
        return 0;
    }
    let sign = if bytes[0] == b'-' { -1 } else { 1 };
    let h: i64 = offset[1..3].parse().unwrap_or(0);
    let m: i64 = offset[3..5].parse().unwrap_or(0);
    sign * (h * 3600 + m * 60)
}

/// Break a unix timestamp into calendar fields in the given fixed offset.
pub fn civil(time: i64, offset: &str) -> Civil {
    let local = time + offset_seconds(offset);
    let mut days = local.div_euclid(86400);
    let secs = local.rem_euclid(86400);
    let wday = ((days % 7) + 7) as usize % 7;
    // Days since 1970-01-01 to civil date (Howard Hinnant's algorithm).
    days += 719468;
    let era = if days >= 0 { days } else { days - 146096 } / 146097;
    let doe = days - era * 146097;
    let yoe = (doe - doe / 1460 + doe / 36524 - doe / 146096) / 365;
    let y = yoe + era * 400;
    let doy = doe - (365 * yoe + yoe / 4 - yoe / 100);
    let mp = (5 * doy + 2) / 153;
    let d = doy - (153 * mp + 2) / 5 + 1;
    let m = if mp < 10 { mp + 3 } else { mp - 9 };
    let year = if m <= 2 { y + 1 } else { y };
    Civil {
        year,
        month: m as u32,
        day: d as u32,
        hour: (secs / 3600) as u32,
        min: ((secs % 3600) / 60) as u32,
        sec: (secs % 60) as u32,
        wday,
    }
}

/// `Fri, 7 Aug 2026 14:13:32 +0000`
pub fn format_log(time: i64, offset: &str) -> String {
    let c = civil(time, offset);
    format!(
        "{}, {} {} {} {:02}:{:02}:{:02} {}",
        DAYS[c.wday],
        c.day,
        MONTHS[(c.month - 1) as usize],
        c.year,
        c.hour,
        c.min,
        c.sec,
        offset
    )
}

/// `2026-08-07 14:15:55 +0000`
pub fn format_meta(time: i64, offset: &str) -> String {
    let c = civil(time, offset);
    format!(
        "{:04}-{:02}-{:02} {:02}:{:02}:{:02} {}",
        c.year, c.month, c.day, c.hour, c.min, c.sec, offset
    )
}

/// `Fri Aug 7 14:15:55 2026 +0000` (git's default log format)
pub fn format_git(time: i64, offset: &str) -> String {
    let c = civil(time, offset);
    format!(
        "{} {} {} {:02}:{:02}:{:02} {} {}",
        DAYS[c.wday],
        MONTHS[(c.month - 1) as usize],
        c.day,
        c.hour,
        c.min,
        c.sec,
        c.year,
        offset
    )
}

/// `Fri, 7 Aug 2026 14:15:55 +0000` for email headers.
pub fn format_rfc2822(time: i64, offset: &str) -> String {
    format_log(time, offset)
}

pub fn now() -> (i64, String) {
    let secs = std::time::SystemTime::now()
        .duration_since(std::time::UNIX_EPOCH)
        .map(|d| d.as_secs() as i64)
        .unwrap_or(0);
    (secs, local_offset(secs))
}

/// Determine the local timezone offset by asking git.
pub fn local_offset(_secs: i64) -> String {
    if let Some(tz) = std::env::var("TZ").ok() {
        let _ = tz;
    }
    // `git var GIT_AUTHOR_IDENT` reports the offset git itself would use.
    if let Ok(ident) = crate::git::run(["var", "GIT_AUTHOR_IDENT"]) {
        let sig = crate::git::parse_ident(&ident);
        return sig.offset;
    }
    "+0000".to_string()
}

